const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;display:flex;flex-direction:column;gap:6px;padding:10px;height:100%;min-height:0;min-width:0;overflow:hidden;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;cursor:pointer}\n.hd{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;flex:none}\n.ttl{display:flex;align-items:center;gap:6px;min-width:0}\n.t{font-weight:700;font-size:14px;white-space:nowrap}\n.ro{font-size:10px;padding:0 5px;border:1px solid var(--line);border-radius:8px;color:var(--muted);white-space:nowrap}\n.ib{flex:none;background:var(--button-paper,transparent);border:1px solid var(--line);border-radius:8px;padding:2px 8px;color:var(--ink);white-space:nowrap}\n.find{flex:none;width:100%;min-height:30px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-weight:700;padding:5px 12px}\n.find:disabled{opacity:.6;cursor:default}\n.find.alt{background:var(--button-paper,var(--panel-paper));color:var(--ink);border:1px solid var(--line)}\n.hint{flex:none;font-size:10.5px;color:var(--muted)}\n.sum{flex:none;display:flex;flex-direction:column;gap:2px;font-size:11px;color:var(--muted)}\n.sum div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sum b{color:var(--ink);margin-right:6px}\n.scroller{flex:1 1 0;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px}\n.scroller>*{flex:none}\n.scroller.pad{padding-right:2px}\n.status{display:flex;flex-direction:column;gap:2px}\n.srow{display:flex;gap:6px;align-items:baseline;font-size:11px;color:var(--muted)}\n.srow b{flex:none;color:var(--ink)}\n.srow span{min-width:0;word-break:break-word}\n.tabs{position:sticky;top:0;z-index:1;display:flex;gap:4px;overflow-x:auto;padding:2px 0;background:var(--paper)}\n.tab{flex:none;border:1px solid var(--line);background:transparent;border-radius:999px;padding:2px 9px;color:var(--ink);white-space:nowrap}\n.tab.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:700}\n.list{display:flex;flex-direction:column;gap:6px}\n.it{display:flex;gap:7px;align-items:flex-start;padding:6px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.chk{flex:none;width:22px;height:22px;padding:0;border:1.5px solid var(--accent);border-radius:6px;background:var(--paper);color:var(--accent);font-weight:700;line-height:1}\n.bd{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;text-align:left;background:none;border:0;padding:0}\n.subj{font-weight:600;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-word}\n.meta,.cue{color:var(--muted);font-size:10.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tags{display:flex;flex-wrap:wrap;gap:3px}\n.tag{font-style:normal;font-size:10px;padding:0 5px;border-radius:6px;background:var(--soft);color:var(--ink);white-space:nowrap}\n.tag.ok{border:1px solid var(--accent)}\n.it.done .subj{text-decoration:line-through;opacity:.65}\n.it.done{opacity:.8}\n.empty{padding:14px 6px;color:var(--muted);text-align:center;line-height:1.5}\n.foot{color:var(--muted);font-size:10.5px;text-align:center;padding:2px}\n.kv b{display:block;font-size:10.5px;color:var(--muted);font-weight:600}\n.v{word-break:break-word;white-space:pre-wrap}\n.mono{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;word-break:break-all}\n\n.form{display:grid;grid-template-columns:1fr 1fr;gap:6px 8px;min-width:0}\n.form .wide{grid-column:1/-1}\n.fld{display:flex;flex-direction:column;gap:2px;min-width:0}\n.lb{font-size:10.5px;color:var(--muted);font-weight:600}\n.in{width:100%;min-width:0;height:28px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);padding:0 6px;font:inherit}\n.dates{display:flex;gap:4px;align-items:center;min-width:0}\n.dates .in{flex:1}\n.to{flex:none;color:var(--muted);font-size:11px}\n.presets{display:flex;flex-wrap:wrap;gap:4px}\n.chip{border:1px solid var(--line);background:var(--button-paper,transparent);color:var(--ink);border-radius:999px;padding:1px 8px;font-size:11px}\n.err{border:1px solid var(--accent);border-radius:8px;padding:4px 6px;word-break:break-word}\n.note{font-size:10.5px;color:var(--muted);line-height:1.45}\n.frow{flex:none;display:flex;gap:8px;align-items:center}\n.frow .find{width:auto;min-width:120px}\n.frow .hint{flex:1;min-width:0}\n.cols{flex:1 1 0;min-height:0;display:grid;grid-template-columns:132px minmax(0,1fr);gap:8px}\n.lc{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:0;overflow:auto}\n.card[data-size=\"3x3\"]{padding:8px;gap:5px}\n.card[data-size=\"3x3\"] .cue{display:none}\n.card[data-size=\"3x3\"] .find{min-height:28px;padding:3px 10px}\n.card[data-size=\"3x3\"] .form,.card[data-size=\"3x6\"] .form{grid-template-columns:1fr}\n.card[data-size=\"3x3\"] .dates,.card[data-size=\"3x6\"] .dates{flex-direction:column;align-items:stretch;gap:2px}\n.card[data-size=\"3x3\"] .dates .to,.card[data-size=\"3x6\"] .dates .to{text-align:center}\n.card[data-size=\"6x3\"]{padding:8px}\n.card[data-size=\"6x6\"]{padding:12px;gap:8px}\n";
const MAIL_SRC = 'connected.mail.message-list';
const CATS = [
  { k: 'reply', label: '要回复' },
  { k: 'prepare', label: '要准备' },
  { k: 'attend', label: '要参加' }
];
const RULES = {
  reply: ['请回复', '请答复', '请回', '回复我', '待回复', '需回复', '尽快回复', '盼复', '请确认', '请告知', '请反馈', '请审批', '请审阅', '等你回复', '请查看并', 'reply', 'respond', 'please confirm', 'let me know', 'your response', 'rsvp', 'action required', 'awaiting your'],
  prepare: ['准备', '材料', '截止', '提交', '报名', '前完成', '之前完成', '待办', '议程', '预习', '提前', '评审', 'deadline', 'due', 'review', 'draft', 'agenda', 'pre-read', 'prepare'],
  attend: ['会议', '邀请', '参会', '参加', '活动', '面试', '讲座', '沙龙', '培训', '研讨', '日程', 'meeting', 'invite', 'invitation', 'webinar', 'interview', 'calendar', 'sync']
};
const SKIP_RE = /sent|draft|trash|spam|junk|已发送|草稿|已删除|垃圾/i;

function pad(n) { return n < 10 ? '0' + n : '' + n; }
function ymd(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function addDays(n) { const d = new Date(); d.setDate(d.getDate() + n); return ymd(d); }
function mdhm(ts) {
  if (!ts) return '日期未知';
  const d = new Date(ts);
  return pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}
function toTs(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v < 1e12 ? v * 1000 : v;
  if (typeof v === 'string') {
    if (/^\d{10,13}$/.test(v.trim())) { const n = Number(v); return n < 1e12 ? n * 1000 : n; }
    const t = Date.parse(v);
    return isNaN(t) ? null : t;
  }
  return null;
}
function pick(o, keys) {
  for (let i = 0; i < keys.length; i++) {
    const v = o[keys[i]];
    if (v !== null && v !== undefined && v !== '') return v;
  }
  return null;
}
function strOf(v) {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return strOf(v[0]);
  if (typeof v === 'object') return strOf(v.name || v.address || v.email || '');
  return String(v);
}
function extractList(d) {
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') {
    const ks = ['messages', 'items', 'list', 'results', 'data', 'mails', 'emails', 'records'];
    for (let i = 0; i < ks.length; i++) if (Array.isArray(d[ks[i]])) return d[ks[i]];
  }
  return null;
}
function normMail(m, i) {
  if (!m || typeof m !== 'object') return null;
  const subject = strOf(pick(m, ['subject', 'title'])) || '（无主题）';
  const ts = toTs(pick(m, ['date', 'received_at', 'receivedAt', 'received_time', 'receivedDateTime', 'time', 'timestamp', 'internal_date', 'internalDate', 'sent_at', 'sentAt', 'created_at']));
  const id = strOf(pick(m, ['id', 'message_id', 'messageId', 'mid', 'uid'])) || (subject + '|' + (ts || i));
  const where = [m.folder, m.mailbox_folder, m.label, m.labels].map(strOf).join(' ');
  let unread = null;
  const rd = pick(m, ['is_read', 'isRead', 'read', 'seen']);
  const ur = pick(m, ['unread', 'is_unread', 'isUnread']);
  if (typeof ur === 'boolean') unread = ur;
  else if (typeof rd === 'boolean') unread = !rd;
  return {
    id: id, subject: subject.slice(0, 200), from: strOf(pick(m, ['from', 'sender', 'from_name', 'fromName', 'from_address', 'fromAddress'])).slice(0, 120),
    ts: ts, snippet: strOf(pick(m, ['snippet', 'preview', 'summary', 'abstract', 'body_preview', 'bodyPreview'])).slice(0, 240),
    unread: unread, skip: SKIP_RE.test(where)
  };
}
function classify(m) {
  const text = (m.subject + ' ' + m.snippet).toLowerCase();
  const isThread = /^\s*(re|回复|答复)\s*[:：]/i.test(m.subject);
  const cats = [];
  const cues = [];
  CATS.forEach(function (c) {
    const hit = RULES[c.k].filter(function (w) { return text.indexOf(w.toLowerCase()) >= 0; });
    if (c.k === 'reply' && !isThread && /[?？]/.test(m.subject)) hit.push('主题含问号');
    if (hit.length) { cats.push(c.k); hit.slice(0, 3).forEach(function (w) { cues.push(w); }); }
  });
  return { cats: cats, cues: cues.filter(function (w, i) { return cues.indexOf(w) === i; }).slice(0, 5) };
}
function buildSnap(list, cfg) {
  const items = [];
  let skipped = 0;
  list.forEach(function (m) {
    if (m.skip) { skipped++; return; }
    if (m.ts) {
      const d = ymd(new Date(m.ts));
      if (d < cfg.from || d > cfg.to) return;
    }
    const c = classify(m);
    items.push({ id: m.id, subject: m.subject, from: m.from, ts: m.ts, snippet: m.snippet, unread: m.unread, cats: c.cats, cues: c.cues });
  });
  items.sort(function (a, b) { return (b.ts || 0) - (a.ts || 0); });
  return { at: Date.now(), from: cfg.from, to: cfg.to, mailbox: cfg.mailbox, calendar: cfg.calendar, total: list.length, skipped: skipped, items: items.slice(0, 300) };
}
function defaultCfg() { return { mailbox: '', calendar: '', from: addDays(-7), to: addDays(7) }; }
function initialize(s) {
  if (s && s.cfg && s.checked) return s;
  return Object.assign({}, s, { cfg: (s && s.cfg) || defaultCfg(), checked: (s && s.checked) || {} });
}

const TABS = [['all', '全部'], ['reply', '回复'], ['prepare', '准备'], ['attend', '参加'], ['other', '其他']];
const PRESETS = [['今起7天', 0, 7], ['前后7天', -7, 7], ['近7天', -7, 0], ['近30天', -30, 0]];
function catLabel(k) { const c = CATS.filter(function (x) { return x.k === k; })[0]; return c ? c.label : k; }
function visible(it, tab) {
  const matched = it.cats.length > 0;
  if (tab === 'all') return matched || it.unread === true;
  if (tab === 'other') return !matched;
  return it.cats.indexOf(tab) >= 0;
}
function validateCfg(d) {
  if (!d.from || !d.to) return '请选择开始和结束日期';
  if (d.from > d.to) return '开始日期不能晚于结束日期';
  return '';
}
function errText(e) {
  const m = typeof e === 'string' ? e : (e && e.message) || '未知错误';
  return /permission_denied|denied|权限/i.test(m) ? '邮箱尚未连接：请先在平台连接邮箱，再点「找出待办」。（' + m + '）' : m;
}
function fullTime(ts) {
  if (!ts) return '日期未知';
  const d = new Date(ts);
  return ymd(d) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}

function mount(ctx) {
  const { root, el, state, ui, update, redraw, size, runAsync, fetchSource } = ctx;
  const h = function (t, a, ...rest) {
    const kids = rest.flat(3).filter(function (x) { return x !== null && x !== undefined && x !== false; });
    return el(t, a || {}, ...kids);
  };
  const big = size === '6x6';
  const small = size === '3x3';
  const cfg = state.cfg || defaultCfg();
  const snap = state.snap || null;
  const checked = state.checked || {};
  ui.page = ui.page || 'main';
  ui.tab = ui.tab || 'all';
  if (!ui.draft) ui.draft = Object.assign({}, cfg);
  const d = ui.draft;
  const job = (ui.jobs && ui.jobs.mail) || null;
  const loading = !!(job && job.status === 'loading');
  const items = snap ? snap.items : [];

  function cleanCfg() {
    return { mailbox: (d.mailbox || '').trim(), calendar: (d.calendar || '').trim(), from: d.from, to: d.to };
  }
  async function saveDraft() {
    const err = validateCfg(d);
    if (err) { ui.cfgErr = err; return false; }
    ui.cfgErr = '';
    const c = cleanCfg();
    try {
      await update(function (s) { return Object.assign({}, s, { cfg: c }); });
      return true;
    } catch (e) {
      ui.cfgErr = '保存失败：' + errText(e);
      return false;
    }
  }
  async function onFind() {
    if (loading) return;
    const ok0 = await saveDraft();
    if (!ok0) { if (!big) ui.page = 'settings'; redraw(); return; }
    const c = cleanCfg();
    if (ui.jobs && ui.jobs.mail) delete ui.jobs.mail;
    ui.scroll = 0;
    const ok = await runAsync('mail', async function () {
      const data = await fetchSource(MAIL_SRC);
      const list = extractList(data);
      if (!list) throw new Error('邮件数据格式无法识别');
      return list.map(normMail).filter(Boolean);
    });
    if (ok) {
      const sn = buildSnap(ui.jobs.mail.data, c);
      try {
        await update(function (s) { return Object.assign({}, s, { snap: sn }); });
      } catch (e) {
        ui.cfgErr = '结果保存失败：' + errText(e);
        redraw();
      }
    }
  }
  function toggle(id) {
    return update(function (s) {
      const c = Object.assign({}, s.checked || {});
      if (c[id]) delete c[id]; else c[id] = Date.now();
      return Object.assign({}, s, { checked: c });
    });
  }
  function go(page) { ui.page = page; redraw(); }

  function field(label, input) {
    return h('label', { class: 'fld' }, h('span', { class: 'lb' }, label), input);
  }
  function dateIn(k, label) {
    const f = function (e) { d[k] = e.target.value; };
    return h('input', { class: 'in', type: 'date', value: d[k] || '', 'aria-label': label, oninput: f, onchange: f });
  }
  function form(compact) {
    return h('div', { class: 'form' },
      field('邮箱', h('input', { class: 'in', type: 'text', value: d.mailbox || '', placeholder: '邮箱地址或备注名', oninput: function (e) { d.mailbox = e.target.value; } })),
      field('日历', h('input', { class: 'in', type: 'text', value: d.calendar || '', placeholder: '日历名称', oninput: function (e) { d.calendar = e.target.value; } })),
      h('div', { class: 'fld wide' }, h('span', { class: 'lb' }, '日期范围'),
        h('div', { class: 'dates' }, dateIn('from', '开始日期'), h('span', { class: 'to' }, '至'), dateIn('to', '结束日期'))),
      h('div', { class: 'presets wide' }, PRESETS.map(function (p) {
        return h('button', { type: 'button', class: 'chip', onclick: function () { d.from = addDays(p[1]); d.to = addDays(p[2]); redraw(); } }, p[0]);
      })),
      ui.cfgErr ? h('div', { class: 'err wide', role: 'alert' }, '提示：' + ui.cfgErr) : null,
      compact ? null : h('div', { class: 'note wide' }, '邮件读取的是平台为本卡片绑定的邮箱，这里的邮箱名只作记录；日历暂无读取接口，所选日历与范围仅保存备用。')
    );
  }


  function backBar(title, onBack) {
    return h('div', { class: 'hd' },
      h('button', { type: 'button', class: 'ib', onclick: onBack }, '‹ 返回'),
      h('span', { class: 't' }, title));
  }
  function tagsOf(it, done) {
    return h('span', { class: 'tags' },
      it.unread === true ? h('i', { class: 'tag' }, '未读') : null,
      it.cats.map(function (c) { return h('i', { class: 'tag k-' + c }, catLabel(c)); }),
      it.cats.length ? null : h('i', { class: 'tag' }, '未命中线索'),
      done ? h('i', { class: 'tag ok' }, '已核对') : null);
  }
  function row(it) {
    const done = !!checked[it.id];
    return h('div', { class: 'it' + (done ? ' done' : '') },
      h('button', { type: 'button', class: 'chk', 'aria-label': done ? '取消已核对' : '标记已核对', 'aria-pressed': String(done), onclick: function () { toggle(it.id); } }, done ? '✓' : ''),
      h('button', { type: 'button', class: 'bd', 'aria-label': '查看对应邮件：' + it.subject, onclick: function () { ui.sel = it.id; go('detail'); } },
        h('span', { class: 'subj' }, it.subject),
        h('span', { class: 'meta' }, (it.from || '发件人未知') + ' · ' + mdhm(it.ts)),
        it.cues.length ? h('span', { class: 'cue' }, '依据：' + it.cues.join('、')) : null,
        tagsOf(it, done)));
  }
  function statusBox() {
    const L = [];
    const rangeNote = snap && (snap.from !== cfg.from || snap.to !== cfg.to);
    if (loading) L.push(['邮件', '读取中…']);
    else if (job && job.status === 'error') {
      L.push(['邮件', '读取失败：' + errText(job.error)]);
      if (snap) L.push(['', '仍显示上次结果（' + mdhm(snap.at) + '）']);
    } else if (snap) {
      L.push(['邮件', small ? '范围内 ' + items.length + ' 封 · ' + mdhm(snap.at)
        : '读取 ' + snap.total + ' 封，范围 ' + snap.from.slice(5) + '~' + snap.to.slice(5) + ' 内 ' + items.length + ' 封' + (snap.skipped ? '，略过已发送/草稿/垃圾 ' + snap.skipped + ' 封' : '') + ' · 更新于 ' + mdhm(snap.at)]);
    } else L.push(['邮件', '尚未查找']);
    if (rangeNote) L.push(['', '日期范围已更改，点「找出待办」重新查找']);
    L.push(['日历', small ? '未接入' : (cfg.calendar ? '「' + cfg.calendar + '」' : '') + '未接入：平台暂无日历读取接口，无法列出日程；所选日历与范围已保留']);
    return h('div', { class: 'status' }, L.map(function (r) {
      return h('div', { class: 'srow' }, r[0] ? h('b', {}, r[0]) : null, h('span', {}, r[1]));
    }));
  }
  function tabsBar() {
    return h('div', { class: 'tabs' }, TABS.map(function (t) {
      const n = items.filter(function (it) { return visible(it, t[0]); }).length;
      const on = ui.tab === t[0];
      return h('button', { type: 'button', class: 'tab' + (on ? ' on' : ''), 'aria-pressed': String(on), onclick: function () { ui.tab = t[0]; ui.scroll = 0; redraw(); } }, t[1] + ' ' + n);
    }));
  }
  function listBody() {
    const rows = items.filter(function (it) { return visible(it, ui.tab); });
    if (rows.length) {
      const rest = ui.tab === 'all' ? items.filter(function (it) { return !it.cats.length && it.unread !== true; }).length : 0;
      return [rows.map(row), rest ? h('div', { class: 'foot' }, '另有 ' + rest + ' 封未命中线索的邮件，见「其他」') : null];
    }
    let t;
    if (loading) t = '读取中…';
    else if (!snap) t = '还没有结果。选好邮箱、日历和日期范围后，点「找出待办」。';
    else if (ui.tab === 'all') t = '范围内的邮件里没有发现要回复、准备或参加的事项。日历未接入，日程未检查。';
    else t = '这一类下没有邮件。';
    return h('div', { class: 'empty' }, t);
  }
  function findBtn() {
    return h('button', { type: 'button', class: 'find', disabled: loading, onclick: onFind }, loading ? '读取中…' : '找出待办');
  }
